+import React from 'react';
+import { getTranslations } from 'next-intl/server';
+
+import { getTokenBalance } from '@/data/token-balance';
+import { getDailyClaimAmount } from '@/data/reward';
+import {
+  DialogDescription,
+  DialogHeader,
+  DialogTitle
+} from '@/components/ui/dialog';
+import ClaimTokensDialogClient from '@/components/daily-token/claim-tokens-dialog';
+import { DailyClaimTimeline } from '@/components/daily-token/daily-claim-timeline';
+import { DailyClaimExpirationNote } from '@/components/daily-token/daily-claim-expiration-note';
+import {
+  DAILY_CLAIM_BASE,
+  DAILY_CLAIM_BONUS,
+  DAILY_CLAIM_MAX
+} from '@/constants';
+import CoinIcon from '@/public/images/coin.svg';
+
+/** 依連續天數計算單日可領代幣（含上限） */
+function amountForStreakDay(streakDay: number): number {
+  const amount = DAILY_CLAIM_BASE + streakDay * DAILY_CLAIM_BONUS;
+  return amount >= DAILY_CLAIM_MAX ? DAILY_CLAIM_MAX : amount;
+}
+
+const ClaimTokensDialog = async () => {
+  const t = await getTranslations();
+  const tokenBalance = await getTokenBalance();
+
+  const dailyClaimAmount = await getDailyClaimAmount();
+  let displayStreakLength = dailyClaimAmount.streakLength + 1;
+  let streakLength = dailyClaimAmount.streakLength;
+  let todayAmount = dailyClaimAmount.dailyClaimAmount;
+
+  /** 開發/預覽用：設為 true 時強制顯示彈窗（.env 或 .env.development.local 加 NEXT_PUBLIC_FORCE_SHOW_DAILY_CLAIM_DIALOG=true） */
+  const forceShow =
+    process.env.NEXT_PUBLIC_FORCE_SHOW_DAILY_CLAIM_DIALOG === 'true';
+
+  /**
+   * 開發/預覽用：覆寫連續登入天數以測試不同情境。
+   * 設為數字 N 表示「今天為第 N 天」（例：1=第一天、7=第七天）。需搭配 FORCE_SHOW 或當日可領時才會看到彈窗。
+   * 例：NEXT_PUBLIC_DAILY_CLAIM_DEBUG_STREAK_DAY=5
+   */
+  const debugStreakDay = process.env.NEXT_PUBLIC_DAILY_CLAIM_DEBUG_STREAK_DAY;
+  if (debugStreakDay != null && debugStreakDay !== '') {
+    const n = parseInt(debugStreakDay, 10);
+    if (Number.isInteger(n) && n >= 1) {
+      displayStreakLength = n;
+      streakLength = n - 1;
+      todayAmount = amountForStreakDay(streakLength);
+    }
+  }
+
+  if (!dailyClaimAmount.canClaimToday && !forceShow) {
+    return null;
+  }
+
+  const timelineData = [
+    {
+      labelKey: 'chartToday' as const,
+      amount: todayAmount,
+      isToday: true
+    },
+    {
+      labelKey: 'chartDay1' as const,
+      amount: amountForStreakDay(streakLength + 1),
+      isToday: false
+    },
+    {
+      labelKey: 'chartDay2' as const,
+      amount: amountForStreakDay(streakLength + 2),
+      isToday: false
+    },
+    {
+      labelKey: 'chartDay3' as const,
+      amount: amountForStreakDay(streakLength + 3),
+      isToday: false
+    }
+  ];
+
+  return (
+    <ClaimTokensDialogClient
+      amount={todayAmount}
+      dialogContent={
+        <>
+          <DialogHeader className="flex flex-row items-center justify-between">
+            <DialogTitle className="text-center">
+              {t('dialog.claimDailyTokens.title')}
+            </DialogTitle>
+            <div
+              className="flex flex-row items-center gap-1"
+              aria-label={t('dialog.claimDailyTokens.coinBalance')}
+              title={t('dialog.claimDailyTokens.coinBalance')}
+            >
+              <CoinIcon className="h-5 w-5 shrink-0 text-primary-text" aria-hidden />
+              <span className="font-bold">{tokenBalance}</span>
+            </div>
+          </DialogHeader>
+          <DialogDescription className="flex flex-col items-center justify-center space-y-4">
+            <DailyClaimTimeline
+              data={timelineData}
+              streakStartDay={displayStreakLength}
+            />
+            <DailyClaimExpirationNote />
+          </DialogDescription>
+        </>
+      }
+    />
+  );
+};
+
+export default ClaimTokensDialog;
