+'use client';
+
+import { useTranslations } from 'next-intl';
+import { Calendar, Check } from 'lucide-react';
+
+import CoinIcon from '@/public/images/coin.svg';
+
+export const DAILY_CLAIM_TIMELINE_LABEL_KEYS = [
+  'chartToday',
+  'chartDay1',
+  'chartDay2',
+  'chartDay3'
+] as const;
+
+export type DailyClaimTimelineLabelKey =
+  (typeof DAILY_CLAIM_TIMELINE_LABEL_KEYS)[number];
+
+export interface DailyClaimTimelineItem {
+  labelKey: DailyClaimTimelineLabelKey;
+  amount: number;
+  isToday: boolean;
+}
+
+interface DailyClaimTimelineProps {
+  data: DailyClaimTimelineItem[];
+  /** 連續登入起始日（今天為第 N 天），用於顯示 N、N+1、N+2、N+3 */
+  streakStartDay: number;
+}
+
+export function DailyClaimTimeline({
+  data,
+  streakStartDay
+}: DailyClaimTimelineProps) {
+  const t = useTranslations('dialog.claimDailyTokens');
+
+  return (
+    <div
+      className="w-full rounded-xl border border-border/60 bg-muted/30 px-3 py-5 md:px-4 md:py-6"
+      aria-label={t('timelineAriaLabel')}
+    >
+      {/* 第一行：節點上方 — 日曆 icon ＋ 遞增數字（N、N+1、N+2、N+3） */}
+      <div className="mb-2 flex w-full md:mb-2.5">
+        {data.map((item, index) => {
+          const dayNum = streakStartDay + index;
+          const ariaLabel = t(item.labelKey);
+          return (
+            <div
+              key={`daily-claim-timeline-item-${dayNum}`}
+              className="flex flex-1 items-center justify-center"
+              aria-label={ariaLabel}
+            >
+              <span
+                className={`inline-flex items-center gap-0.5 rounded-full border px-1.5 py-0.5 md:gap-1 md:px-2 md:py-0.5 border-border/60 ${
+                  item.isToday ? 'bg-green-50' : 'bg-muted/50'
+                }`}
+              >
+                <Calendar
+                  className={`h-3 w-3 shrink-0 md:h-3.5 md:w-3.5 ${
+                    item.isToday ? 'text-green-600' : 'text-muted-foreground'
+                  }`}
+                />
+                <span
+                  className={`text-xs tabular-nums font-semibold ${
+                    item.isToday ? 'text-green-600' : 'text-gray-700'
+                  }`}
+                >
+                  {dayNum}
+                </span>
+              </span>
+            </div>
+          );
+        })}
+      </div>
+      {/* 第二行：橫線 + 節點（節點圓心在線上） */}
+      <div className="relative flex w-full">
+        <div
+          className="absolute left-0 right-0 top-1/2 h-0.5 -translate-y-1/2 bg-border"
+          style={{ marginLeft: '8%', marginRight: '8%' }}
+          aria-hidden
+        />
+        {data.map((item) => (
+          <div
+            key={item.labelKey}
+            className="relative z-10 flex h-7 flex-1 items-center justify-center md:h-8"
+          >
+            <div
+              className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full md:h-7 md:w-7 ${
+                item.isToday ? 'bg-green-600' : 'bg-gray-200'
+              }`}
+            >
+              <Check
+                className="h-3.5 w-3.5 text-white md:h-4 md:w-4"
+                strokeWidth={3}
+              />
+            </div>
+          </div>
+        ))}
+      </div>
+      {/* 第三行：代幣數量 + icon */}
+      <div className="mt-2 flex w-full md:mt-2.5">
+        {data.map((item) => (
+          <div
+            key={item.labelKey}
+            className={`flex flex-1 items-center justify-center gap-0.5 text-sm font-semibold tabular-nums md:text-base ${
+              item.isToday ? 'text-primary' : 'text-gray-400 dark:text-gray-500'
+            }`}
+          >
+            <CoinIcon className="h-3.5 w-3.5 md:h-4 md:w-4" />
+            <span>{item.amount}</span>
+          </div>
+        ))}
+      </div>
+    </div>
+  );
+}
