+'use client';
+
+import React, { useState, useEffect } from 'react';
+import { useTranslations } from 'next-intl';
+
+import { DAILY_CLAIM_EXPIRY_MS } from '@/constants';
+
+/**
+ * 將剩餘毫秒格式化為 HH:MM:SS
+ */
+function formatCountdown(ms: number): string {
+  if (ms <= 0) return '00:00:00';
+  const totalSeconds = Math.floor(ms / 1000);
+  const hours = Math.floor(totalSeconds / 3600);
+  const minutes = Math.floor((totalSeconds % 3600) / 60);
+  const seconds = totalSeconds % 60;
+  return [hours, minutes, seconds]
+    .map((n) => n.toString().padStart(2, '0'))
+    .join(':');
+}
+
+/**
+ * 每日領取彈窗內的過期說明與倒數計時。
+ * 倒數表示「若現在領取，代幣有效時間剩餘」。
+ */
+export function DailyClaimExpirationNote() {
+  const t = useTranslations('dialog.claimDailyTokens');
+  const [remainingMs, setRemainingMs] = useState(DAILY_CLAIM_EXPIRY_MS);
+
+  useEffect(() => {
+    const endAt = Date.now() + DAILY_CLAIM_EXPIRY_MS;
+    const tick = () => {
+      const left = endAt - Date.now();
+      setRemainingMs(left > 0 ? left : 0);
+    };
+    tick();
+    const interval = setInterval(tick, 1000);
+    return () => clearInterval(interval);
+  }, []);
+
+  const expirationNote = t('expirationNote');
+
+  return (
+    <div
+      className="w-full text-center"
+      aria-label={expirationNote}
+      title={expirationNote}
+    >
+      <p className="mb-1 text-xs text-muted-foreground">
+        {t('expirationNoteLine1')}
+      </p>
+      <p
+        className="font-mono text-lg font-semibold tabular-nums text-orange-500 md:text-xl"
+        aria-live="polite"
+      >
+        {formatCountdown(remainingMs)}
+      </p>
+    </div>
+  );
+}
